import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:url_launcher/url_launcher.dart';
import '../../../application/itqan_journey_provider.dart';

class ShareJourneyScreen extends ConsumerStatefulWidget{const ShareJourneyScreen({super.key});@override ConsumerState<ShareJourneyScreen> createState()=>_ShareJourneyScreenState();}
class _ShareJourneyScreenState extends ConsumerState<ShareJourneyScreen>{final _message=TextEditingController();bool _sending=false;int _sourceId=1;@override void dispose(){_message.dispose();super.dispose();}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('مشاركة الخير')),body:ListView(padding:const EdgeInsets.all(20),children:[const Text('اكتب فائدة أو ذكراً أو دعاءً موثوقاً لمشاركته.'),const SizedBox(height:12),TextField(controller:_message,minLines:4,maxLines:8,textDirection:TextDirection.rtl,decoration:const InputDecoration(border:OutlineInputBorder(),hintText:'أدخل المحتوى الذي تريد مشاركته')),const SizedBox(height:12),DropdownButton<int>(value:_sourceId,items:const[DropdownMenuItem(value:1,child:Text('مرجع 1')),DropdownMenuItem(value:2,child:Text('مرجع 2')),DropdownMenuItem(value:3,child:Text('مرجع 3'))],onChanged:(v){if(v!=null)setState(()=>_sourceId=v);}),FilledButton.icon(onPressed:_sending?null:_share,icon:const Icon(Icons.sms_outlined),label:Text(_sending?'جارٍ فتح المشاركة':'مشاركة عبر الرسائل'))]));Future<void> _share()async{final text=_message.text.trim();if(text.isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('أدخل محتوى المشاركة أولاً')));return;}setState(()=>_sending=true);try{final uri=Uri(scheme:'sms',queryParameters:{'body':text});final opened=await launchUrl(uri,mode:LaunchMode.externalApplication);if(!opened)throw StateError('تعذر فتح تطبيق الرسائل');final result=await ref.read(itqanJourneyProvider.notifier).recordActivity('share',metadata:{'source_id':_sourceId});if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('تم تسجيل المشاركة بعد قبول الخادم • ${result['data']?['xp_earned']??0} XP')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('لم يتم تسجيل النشاط: $e')));}finally{if(mounted)setState(()=>_sending=false);}}
}
